// 1. Obtener legisladores master de DipuData
const legisladores = $('HTTP Request Legisladores').all().map(item => item.json);

// 2. Obtener lista de asesores parseada del CSV
const asesoresRows = $('Extract CSV Asesores').all().map(item => item.json);

// 3. Obtener lista de proyectos de ley parseada del CSV
const proyectosRows = $('Extract CSV Proyectos').all().map(item => item.json);

// Escala salarial aproximada mensual por categoría parlamentaria (HCDN / HSN)
const ESCALA_CATEGORIAS_ARS = {
  'A-1': 2450000,
  'A-2': 2100000,
  'A-3': 1850000,
  'A-4': 1600000,
  'A-5': 1400000,
  'A-6': 1250000,
  'A-7': 1100000,
  'A-8': 950000,
  'A-9': 850000,
  'A-10': 780000,
  'A-11': 700000,
  'A-12': 650000,
  'A-13': 600000,
  'A-14': 550000,
  'default': 1500000
};

function extraerApellidos(nombreCompleto) {
  if (!nombreCompleto) return [];
  const ignorar = new Set(['de', 'del', 'la', 'las', 'los', 'san', 'y', 'el', 'di', 'da']);
  return String(nombreCompleto)
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z\s]/g, '')
    .split(/\s+/)
    .filter(p => p.length >= 3 && !ignorar.has(p));
}

const resultado = [];

for (const leg of legisladores) {
  const legId = Number(leg.id);
  const recinto = String(leg.id_recinto || '').trim();
  const nombreLeg = String(leg.nombre || '').trim();
  const apellidosLeg = new Set(extraerApellidos(nombreLeg));

  // Filtrar asesores del legislador
  const asesoresLeg = asesoresRows.filter(a => {
    const asig = String(a.legislador_asignado || a.id_recinto || a.legislador || '').trim();
    if (!asig) return false;
    if (recinto && asig.toLowerCase() === recinto.toLowerCase()) return true;
    return asig.toLowerCase() === nombreLeg.toLowerCase();
  });

  const totalAsesores = asesoresLeg.length;
  let costoMensual = 0;
  let alertasNepotismo = 0;
  const detalleAsesores = [];

  for (const as of asesoresLeg) {
    const cat = String(as.categoria || 'default').toUpperCase().trim();
    const sueldo = as.sueldo_mensual ? Number(as.sueldo_mensual) : (ESCALA_CATEGORIAS_ARS[cat] || ESCALA_CATEGORIAS_ARS['default']);
    costoMensual += sueldo;

    const nombreAsesor = String(as.nombre_asesor || as.nombre || '').trim();
    const apellidosAsesor = extraerApellidos(nombreAsesor);
    const coincide = apellidosAsesor.some(ap => apellidosLeg.has(ap));

    if (coincide) {
      alertasNepotismo++;
    }

    detalleAsesores.push({
      nombre: nombreAsesor,
      categoria: cat,
      monto_mensual: sueldo,
      alerta_nepotismo: coincide
    });
  }

  const anio = 2024;
  const costoAnual = costoMensual * 13; // 12 meses + SAC (Aguinaldo)

  // Filtrar proyectos donde es Autor
  const proyectosAutor = proyectosRows.filter(p => {
    const pRecinto = String(p.legislador_id_recinto || p.id_recinto || p.legislador || '').trim();
    const rol = String(p.rol || '').trim().toLowerCase();
    const matchLeg = (recinto && pRecinto.toLowerCase() === recinto.toLowerCase()) || (pRecinto.toLowerCase() === nombreLeg.toLowerCase());
    return matchLeg && (rol === 'autor' || rol === 'autor principal');
  });

  const cantProyectos = proyectosAutor.length;
  const costoPorProyecto = cantProyectos > 0 ? Math.round((costoAnual / cantProyectos) * 100) / 100 : costoAnual;

  resultado.push({
    json: {
      legislador_id: legId,
      id_recinto: recinto,
      nombre_legislador: nombreLeg,
      anio: anio,
      total_asesores: totalAsesores,
      costo_mensual_ars: costoMensual,
      costo_anual_ars: costoAnual,
      alertas_nepotismo: alertasNepotismo,
      proyectos_autor_anio: cantProyectos,
      costo_por_proyecto_ars: costoPorProyecto,
      detalle_asesores_json: JSON.stringify(detalleAsesores),
      fuente: 'n8n.buceo.co'
    }
  });
}

return resultado;
